def digit_sum(n):
    if n == 0:
        return 0
    return n % 10 + digit_sum(n // 10)

def single_digit(n):
    if n < 10:
        return n
    return single_digit(digit_sum(n))

n = int(input())
print(digit_sum(n))
print(single_digit(n))

